gates.script:
[ -n "$CI_UNIT_SHARDS" ] || { echo "★ FAIL static の出力が空（G0 が流れていない）"; exit 1; }
if [ "$CI_UNIT_SHARDS" = "0" ]; then echo "流す試験 0 本（チケットの CI の範囲・G0）"; exit 0; fi
n=$(ls .vitest-reports/blob-*-"$CI_UNIT_SHARDS".json 2>/dev/null | wc -l)
[ "$n" -eq "$CI_UNIT_SHARDS" ] || { echo "★ FAIL 分けた単体の試験の結果が $CI_UNIT_SHARDS つのうち $n つしか無い"; exit 1; }
python3 scripts/ci/ci_scope.py run-merge && python3 scripts/ci/ci_scope.py check-count --report .vitest-reports/merged.json

gates.env:
CI_UNIT_FILES: ${{ needs.static.outputs.unit_files }}
CI_COVERAGE_ARGS: ${{ needs.static.outputs.coverage_args }}
CI_UNIT_SHARDS: ${{ needs.static.outputs.unit_shards }}
CI_FULL: ${{ needs.static.outputs.full }}

CI_FULL: ${{ needs.static.outputs.full }}
CI_WEB_SPECS: ${{ needs.static.outputs.web_g48 }}
CI_WEB_OTHER: ${{ needs.static.outputs.web_g59 }}
CI_WEB_TASKS: ${{ needs.static.outputs.web_tasks }}
CI_WEB_GATES: ${{ needs.static.outputs.web_gates }}

CI_FULL: ${{ needs.static.outputs.full }}
CI_WEB_SPECS: ${{ needs.static.outputs.web_g59 }}
CI_WEB_OTHER: ${{ needs.static.outputs.web_g48 }}
CI_WEB_GATES: ${{ needs.static.outputs.web_gates }}

CI_FULL: ${{ needs.static.outputs.full }}
CI_WEB_GATES: ${{ needs.static.outputs.web_gates }}
CI_WEB_SPECS: ${{ needs.static.outputs.web_g48 }}
CI_WEB_OTHER: ${{ needs.static.outputs.web_g59 }}

CI_FULL: ${{ needs.static.outputs.full }}
CI_WEB_GATES: ${{ needs.static.outputs.web_gates }}
CI_WEB_SPECS: ${{ needs.static.outputs.web_g48 }}
CI_WEB_OTHER: ${{ needs.static.outputs.web_g59 }}
